"""Thin model helpers: JSON completions and a tool-calling agent loop.

Every agent run is a neatlogs AGENT span; every tool execution is a TOOL span,
so the trace tree mirrors the orchestration.
"""
import json
import re
from dataclasses import dataclass
from typing import Any, Callable

import neatlogs

from .config import MODEL, client


def parse_json(text: str) -> Any:
    """Parse JSON from a model reply, tolerating ``` fences and leading prose."""
    text = text.strip()
    m = re.search(r"```(?:json)?\s*(.*?)```", text, re.S)
    if m:
        text = m.group(1).strip()
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        start = min([i for i in (text.find("{"), text.find("[")) if i >= 0] or [0])
        return json.loads(text[start:])


def complete(system: str, user: str, model: str = MODEL, max_tokens: int = 4000) -> str:
    resp = client().chat.completions.create(
        model=model,
        max_tokens=max_tokens,
        messages=[{"role": "system", "content": system}, {"role": "user", "content": user}],
    )
    return resp.choices[0].message.content or ""


def complete_json(system: str, user: str, model: str = MODEL, max_tokens: int = 4000) -> Any:
    return parse_json(complete(system + "\nReply with JSON only, no prose.", user, model, max_tokens))


@dataclass
class Tool:
    name: str
    description: str
    parameters: dict
    fn: Callable[..., Any]

    def spec(self) -> dict:
        return {
            "type": "function",
            "function": {"name": self.name, "description": self.description, "parameters": self.parameters},
        }


def run_tool_agent(
    name: str,
    system: str,
    user: str,
    tools: list[Tool],
    max_steps: int = 12,
    model: str = MODEL,
    log: Callable[[str], None] = print,
) -> str:
    """Run a tool-using agent until it answers in plain text (expected JSON)."""

    @neatlogs.span(kind="AGENT", name=name)
    def _run() -> str:
        by_name = {t.name: t for t in tools}
        messages: list[dict] = [{"role": "system", "content": system}, {"role": "user", "content": user}]
        for step in range(max_steps):
            resp = client().chat.completions.create(
                model=model,
                max_tokens=6000,
                messages=messages,
                tools=[t.spec() for t in tools],
            )
            msg = resp.choices[0].message
            if not msg.tool_calls:
                return msg.content or ""
            messages.append(msg.model_dump(exclude_none=True))
            for call in msg.tool_calls:
                tool = by_name[call.function.name]
                args = json.loads(call.function.arguments or "{}")
                log(f"  [{name}] {tool.name}({', '.join(f'{k}={str(v)[:60]!r}' for k, v in args.items())})")
                result = _call_tool(tool, args)
                messages.append({"role": "tool", "tool_call_id": call.id, "content": result})
        # Out of steps: force a final answer without tools.
        messages.append({"role": "user", "content": "Stop using tools and give your final JSON answer now."})
        resp = client().chat.completions.create(model=model, max_tokens=6000, messages=messages)
        return resp.choices[0].message.content or ""

    return _run()


def _call_tool(tool: Tool, args: dict) -> str:
    with neatlogs.trace(tool.name, kind="TOOL") as span:
        span.set_attribute("tool.args", json.dumps(args)[:2000])
        try:
            out = tool.fn(**args)
        except Exception as e:  # the model should see failures and adapt
            out = {"error": f"{type(e).__name__}: {e}"}
        text = out if isinstance(out, str) else json.dumps(out, ensure_ascii=False)
        span.set_attribute("tool.result_chars", len(text))
        return text[:20000]

"""Workspace: one folder per applicant, one JSON file per artifact.

Each orchestration step writes its result to disk when it finishes. A re-run
skips steps whose result file already exists, which is how a crashed run resumes.
"""
import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


class Workspace:
    def __init__(self, root: Path):
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)

    def path(self, key: str) -> Path:
        return self.root / f"{key}.json"

    def has(self, key: str) -> bool:
        return self.path(key).exists()

    def load(self, key: str, default: Any = None) -> Any:
        p = self.path(key)
        if not p.exists():
            return default
        return json.loads(p.read_text())

    def save(self, key: str, data: Any) -> None:
        p = self.path(key)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps(data, indent=2, ensure_ascii=False))
        self._log(f"saved {key}")

    def _log(self, line: str) -> None:
        ts = datetime.now(timezone.utc).isoformat(timespec="seconds")
        with (self.root / "run.log").open("a") as f:
            f.write(f"{ts} {line}\n")

"""OpenAlex lookups: find an author and list their recent works. No API key needed."""
import httpx

from ..llm import Tool

BASE = "https://api.openalex.org"
HEADERS = {"User-Agent": "hioffer (mailto:hioffer@example.com)"}


def _get(path: str, **params) -> dict:
    r = httpx.get(f"{BASE}{path}", params=params, headers=HEADERS, timeout=30)
    r.raise_for_status()
    return r.json()


def find_author(name: str, institution: str = "") -> dict:
    data = _get("/authors", search=name, per_page=5)
    out = []
    for a in data.get("results", []):
        insts = [i.get("display_name", "") for i in a.get("last_known_institutions", [])]
        if institution and not any(institution.lower() in i.lower() for i in insts):
            continue
        out.append(
            {
                "id": a["id"].rsplit("/", 1)[-1],
                "name": a.get("display_name"),
                "institutions": insts,
                "works_count": a.get("works_count"),
                "cited_by_count": a.get("cited_by_count"),
                "topics": [t.get("display_name") for t in a.get("topics", [])[:5]],
            }
        )
    return {"candidates": out}


def recent_works(author_id: str, since_year: int = 2024, limit: int = 6) -> dict:
    data = _get(
        "/works",
        filter=f"authorships.author.id:{author_id},from_publication_date:{since_year}-01-01",
        sort="cited_by_count:desc",
        per_page=limit,
    )
    works = []
    for w in data.get("results", []):
        loc = w.get("primary_location") or {}
        src = loc.get("source") or {}
        works.append(
            {
                "id": w["id"].rsplit("/", 1)[-1],
                "title": w.get("title"),
                "year": w.get("publication_year"),
                "venue": src.get("display_name"),
                "cited_by": w.get("cited_by_count"),
                "url": loc.get("landing_page_url") or w.get("doi") or w["id"],
                "authors": [a["author"]["display_name"] for a in w.get("authorships", [])[:6]],
            }
        )
    return {"author_id": author_id, "works": works}


FIND_AUTHOR = Tool(
    name="find_author",
    description="Look up a researcher on OpenAlex by name (optionally filtered by institution). Returns candidate "
    "author ids with institutions and topics.",
    parameters={
        "type": "object",
        "properties": {
            "name": {"type": "string"},
            "institution": {"type": "string", "description": "Substring of the institution name, e.g. 'Washington'"},
        },
        "required": ["name"],
    },
    fn=find_author,
)

RECENT_WORKS = Tool(
    name="recent_works",
    description="List an OpenAlex author's most-cited works since a given year, with titles, venues and URLs.",
    parameters={
        "type": "object",
        "properties": {
            "author_id": {"type": "string", "description": "OpenAlex author id like A5067919401"},
            "since_year": {"type": "integer", "default": 2024},
        },
        "required": ["author_id"],
    },
    fn=recent_works,
)

"""Read applicant-provided files (markdown, text, PDF)."""
import io
from pathlib import Path


def pdf_text(data: bytes) -> str:
    from pypdf import PdfReader

    reader = PdfReader(io.BytesIO(data))
    return "\n".join((p.extract_text() or "") for p in reader.pages)


def read_file(path: Path) -> str:
    path = Path(path)
    if path.suffix.lower() == ".pdf":
        return pdf_text(path.read_bytes())
    return path.read_text(errors="replace")


def word_count(text: str) -> int:
    return len(text.split())

"""Verifier: deterministic checks first, then an LLM audit of claims against sources."""
import json
import re

import neatlogs

from ..llm import complete_json

AUDIT_SYSTEM = """You audit a PhD applicant's drafted materials against their sources.
For each draft, find sentences that state a fact about the applicant or an advisor which is either
(a) missing a citation tag, or (b) cited to a source that does not support it.
Be strict about invented specifics (numbers, names, titles, venues) and lenient about phrasing.
Return JSON: {"issues": [{"where": "sop|fit:<advisor>|email:<advisor>", "sentence": str, "problem": str}]}"""

TAG = re.compile(r"\[(lib|paper):([^\]]+)\]")


@neatlogs.span(kind="GUARDRAIL", name="verifier")
def verify(library: dict, program: dict, advisors: dict, materials: dict) -> dict:
    issues: list[dict] = []
    lib_ids = {i["id"] for i in library["items"]}
    paper_ids = {p["id"] for a in advisors["advisors"] for p in a.get("papers", [])}

    # 1. Word limit.
    sop = materials["sop"]
    if sop.get("word_limit") and sop["word_count"] > sop["word_limit"]:
        issues.append({"check": "word_limit", "problem": f"SOP is {sop['word_count']} words, limit {sop['word_limit']}"})

    # 2. Citation tags must resolve.
    texts = {"sop": sop["text"]}
    texts.update({f"fit:{p['advisor']}": p["text"] for p in materials.get("fit_paragraphs", [])})
    texts.update({f"email:{e['advisor']}": e["body"] for e in materials.get("emails", [])})
    for where, text in texts.items():
        for kind, ident in TAG.findall(text):
            ref = f"{kind}:{ident}" if kind == "lib" else ident
            if (kind == "lib" and ref not in lib_ids) or (kind == "paper" and ident not in paper_ids):
                issues.append({"check": "citation", "where": where, "problem": f"unknown citation [{kind}:{ident}]"})
    if not TAG.search(sop["text"]):
        issues.append({"check": "citation", "where": "sop", "problem": "SOP has no citation tags at all"})

    # 3. Requirement coverage: each required document must map to a library item or a draft.
    have = {i["type"] for i in library["items"]} | {"sop"}
    for f in program.get("facts", []):
        need = {"cv": "cv", "writing_sample": "writing_sample", "research_statement": "research_statement"}.get(f["key"])
        if need and need not in have and "not required" not in f["value"].lower() and "optional" not in f["value"].lower():
            issues.append({"check": "coverage", "problem": f"program requires {need} but library has none"})

    # 4. LLM audit of claims vs sources.
    audit = complete_json(
        AUDIT_SYSTEM,
        "LIBRARY (ids and facts):\n"
        + json.dumps([{"id": i["id"], "key_facts": i["key_facts"]} for i in library["items"]], ensure_ascii=False)
        + "\n\nPAPERS:\n"
        + json.dumps([{"id": p["id"], "title": p["title"], "advisor": a["name"]} for a in advisors["advisors"] for p in a["papers"]], ensure_ascii=False)
        + "\n\nDRAFTS:\n"
        + json.dumps(texts, ensure_ascii=False),
    )
    for it in audit.get("issues", []):
        issues.append({"check": "claim", **it})

    return {"passed": not issues, "issues": issues}

